-- 人行中债销售区域报送数据接口 表新增
DROP TABLE IF EXISTS `PBC_SALE_SVRREPORT`;
create table PBC_SALE_SVRREPORT
(
    SENDDATE                 date     null comment '下发日期',
    PROD_ID                  varchar(20)    null comment '产品代码',
    ISSUEMEMBER              varchar(9)     null comment '法人行',
    CUS_TYPE                 varchar(1)     null comment '客户类型',
    IS_Consignment           varchar(2)     null comment '是否其他机构代销',
    AREA_CODE                varchar(10)    null comment '行政区域代码',
    CCY                      varchar(50)    null comment '币种',
    PRINAMT                  decimal(30, 2) null comment '认购金额',
    PRINAMT_RMB              decimal(30, 2) null comment '认购金额转人民币',
    PRINAMT_CONFIRM          decimal(30, 2) null comment '认购确认份额',
    PRINAMT_NUMBER           decimal(30, 2) null comment '认购客户数',
    SG_AMT                   decimal(30, 2) null comment '申购金额',
    SG_AMT_RMB               decimal(30, 2) null comment '申购金额转人民币',
    SG_CONFIRM_AMT           decimal(30, 2) null comment '申购确认份额',
    SH_AMT                   decimal(30, 2) null comment '赎回兑付金额',
    SH_AMT_RMB               decimal(30, 2) null comment '赎回兑付金额转人民币',
    SH_PRINCIPAL             decimal(30, 2) null comment '赎回兑付本金',
    SH_PRINCIPAL_RMB         decimal(30, 2) null comment '赎回兑付本金转人民币',
    SH_QTY                   decimal(30, 2) null comment '赎回兑付份额',
    EXPIRE_AMT               decimal(30, 2) null comment '到期兑付金额',
    EXPIRE_AMT_RMB           decimal(30, 2) null comment '到期兑付金额转人民币',
    EXPIRE_AMT_PRINCIPAL     decimal(30, 2) null comment '到期兑付本金',
    EXPIRE_AMT_PRINCIPAL_RMB decimal(30, 2) null comment '到期兑付本金转人民币',
    EXPIRE_AMT_QTY           decimal(30, 2) null comment '到期兑付份额',
    REBONUS_AMT              decimal(30, 2) null comment '红利再投资金额',
    REBONUS_AMT_RMB          decimal(30, 2) null comment '红利再投资金额转人民币',
    REBONUS_AMT_QTY          decimal(30, 2) null comment '红利再投资份额',
    BONUS_AMT                decimal(30, 2) null comment '现金分红金额',
    BONUS_AMT_RMB            decimal(30, 2) null comment '现金分红金额转人民币',
    QTY_ADD_AMT              decimal(30, 2) null comment '份额强增金额',
    QTY_ADD_AMT_RMB          decimal(30, 2) null comment '份额强增金额转人民币',
    QTY_ADD                  decimal(30, 2) null comment '强增份额',
    QTY_MINUS_PRINCIPAL      decimal(30, 2) null comment '强减本金',
    QTY_MINUS_PRINCIPAL_RMB  decimal(30, 2) null comment '强减本金转人民币',
    QTY_MINUS                decimal(30, 2) null comment '强减份额',
    SAVE_AMT                 decimal(30, 2) null comment '保有量本金',
    SAVE_AMT_RMB             decimal(30, 2) null comment '保有量本金转人民币',
    SAVE_QTY                 decimal(30, 2) null comment '保有量份额',
    SAVE_CUS_NUM             decimal(30, 2) null comment '保有量客户数',
    EXCHANGE_RATE            decimal(30, 2) null comment '汇率',
    OUT_TRADE_QTR            decimal(30, 2) null comment '非交易过户出份额',
    OUT_TRADE_AMT            decimal(30, 2) null comment '非交易过户出金额',
    OUT_TRADE_AMT_RMB        decimal(30, 2) null comment '非交易过户出金额转人民币',
    OUT_TRADE_PRINCIPAL      decimal(30, 2) null comment '非交易过户出本金',
    OUT_TRADE_PRINCIPAL_RMB  decimal(30, 2) null comment '非交易过户出本金转人民币',
    IN_TRADE_AMT             decimal(30, 2) null comment '非交易过户入金额',
    IN_TRADE_AMT_RMB         decimal(30, 2) null comment '非交易过户入金额转人民币',
    IN_TRADE_QTR             decimal(30, 2) null comment '非交易过户入份额',
    CREATE_TIME              datetime       NULL DEFAULT NULL COMMENT '创建日期',
    UPDATE_TIME              datetime       NULL DEFAULT NULL COMMENT '更新日期',
    CREATE_USER              varchar(50)    NULL DEFAULT NULL COMMENT '创建人',
    CREATE_DEPT              varchar(10)    NULL DEFAULT NULL COMMENT '创建部门',
    UPDATE_USER              varchar(10)    NULL DEFAULT NULL COMMENT '更新人'
) comment '人行中债销售区域报送数据';

-- 人行中债销售区域报送数据接入 批处理增加
delete from sys_batch_task where TASK_ID='3120';

