delete from sys_datadict_list where DICT_CODE='PBC_CUSTTYPE';

-- 是否其他机构代销字典新增
delete from sys_datadict where DICT_CODE='PBC_CONSIGNMENT';

delete from sys_datadict_list where DICT_CODE='PBC_CONSIGNMENT';

